static const float fc2W[64] = {0.102983326f,-0.0136725521f,0.306740105f,0.241112441f,-0.134579763f,0.227179945f,-0.109540798f,0.0691899285f,0.199900016f,0.245308578f,-0.16275692f,-0.081653662f,-0.115164161f,0.0464308485f,-0.163903505f,-0.163229048f,0.052655071f,0.129134238f,0.0698256195f,-0.0766169727f,-0.121047132f,0.161234364f,-0.0047039506f,-0.0386570133f,-0.0629854575f,0.281909466f,-0.170011386f,0.159649268f,0.16437f,-0.284094483f,0.20892027f,-0.0620884001f,-0.179030418f,-0.0530795865f,0.193608135f,-0.131801635f,-0.148529798f,0.0334880687f,0.0737632439f,-0.0682522058f,-0.0624735244f,0.00214601611f,0.1043998f,0.0135628376f,0.240154386f,-0.226754218f,0.216737419f,-0.143163294f,0.000225054566f,-0.164887801f,0.175212398f,-0.0155523717f,-0.137271404f,0.0891288295f,-0.0972255841f,0.282250911f,-0.0500461683f,0.0456042029f,-0.0998690873f,0.191190079f,0.0320293009f,0.286916643f,0.433067471f,0.215506554f};
